    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]       # 2500, no discount
    second = order(shop, "c1", ("LAMP", 2)).body["order_id"]      # 12000 -> 10800
    third = order(shop, "c1", ("PEN", 1)).body["order_id"]
    order(shop, "c2", ("BOOK", 1))
    shop.orders.handle_cancel(third)
    body = shop.insights.handle_order_history("c1").body
    assert body["customer_id"] == "c1"
    assert body["orders"] == [
        {"order_id": third, "status": "cancelled", "total_cents": 300},
        {"order_id": second, "status": "placed", "total_cents": 10_800},
        {"order_id": first, "status": "placed", "total_cents": 2_500},
    ]
    for entry in body["orders"]:
        assert entry["total_cents"] == shop.orders.handle_get(entry["order_id"]).body["total_cents"]


