    oid = order(shop, "c2", ("LAMP", 2)).body["order_id"]  # 12000 -> 15% off = 10200
    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert entry == {"order_id": oid, "status": "placed", "total_cents": 10_200}

