"""Customer insight endpoints for the account team."""

from __future__ import annotations

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import (InvalidRequest, Response, bad_request, not_found,
                                     require_positive_int)
from orders.domain.orders import Order
from orders.infrastructure.customers import InMemoryCustomerRepository


class CustomerInsightsController:
    def __init__(self, service: OrderService, customers: InMemoryCustomerRepository) -> None:
        self._service = service
        self._customers = customers

    def _lifetime_value(self, orders: list[Order]) -> tuple[int, int]:
        """(count, total cents) over the non-cancelled orders."""
        active = [o for o in orders if o.status != "cancelled"]
        return len(active), sum(self._service.summarize(o).total_cents for o in active)

    def handle_top_customers(self, limit: int) -> Response:
        """Customers ranked by lifetime value, highest first, then customer_id."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, value = self._lifetime_value(self._service.list_for_customer(customer.customer_id))
            if value > 0:
                ranked.append((customer.customer_id, customer.name, value))
        ranked.sort(key=lambda r: (-r[2], r[0]))
        return Response(200, {"customers": [
            {"customer_id": cid, "name": name, "lifetime_value_cents": value}
            for cid, name, value in ranked[:limit]]})

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with discounted totals."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        entries = []
        # The repository returns creation order, so reverse for newest first.
        for order in reversed(orders):
            summary = self._service.summarize(order)
            entries.append({"order_id": order.order_id, "status": order.status,
                            "total_cents": summary.total_cents})
        return Response(200, {"customer_id": customer_id, "orders": entries})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and discounted total of a customer's non-cancelled orders."""
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        count, total = self._lifetime_value(orders)
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": total})

